CATALOG = {"zh-TW": _ZH, "en": _EN, "ja": _JA}


def tr(locale: str, key: str, **kwargs) -> str:
    value = CATALOG.get(locale, _ZH).get(key, _ZH.get(key, key))
    return value.format(**kwargs) if kwargs else value
